const PASSWORD = 'Demo@12345';
const rng = (() => { let a = 20261018; return () => { a |= 0; a = (a + 0x6d2b79f5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; })();
const pick = (arr) => arr[Math.floor(rng() * arr.length)];
