function mkUser(key, name, email, role, { phone, lang = 'en', label } = {}) {
  const id = insert('users', { email, name, phone, password_hash: hashPassword(PASSWORD), role, lang, demo_label: label || null });
  U[key] = get('SELECT * FROM users WHERE id = ?', id);
  if (role === 'customer') for (const [k, g] of [['storage', 1], ['renewal_reminders', 1], ['partner_referrals', 0], ['marketing', 0]]) insert('consents', { user_id: id, kind: k, granted: g });
  return U[key];
}
const fakePdf = (label) => Buffer.from(`%PDF-1.4\n% ${label}\n1 0 obj<</Type/Catalog>>endobj\n${'% demonstration document body — fictional content\n'.repeat(45)}%%EOF\n`);
const fakePng = () => Buffer.concat([Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]), Buffer.alloc(24000, 7)]);

function upload(user, c, profile, kind, meta = {}) {
  return storeDocument({ user, caseId: c.id, profileId: profile?.id, kind, filename: `${kind}-${profile?.full_name?.split(' ')[0]?.toLowerCase() || 'doc'}.${kind === 'photo' ? 'png' : 'pdf'}`, buffer: kind === 'photo' ? fakePng() : fakePdf(`${kind} ${c.ref}`), meta: { holder_name: profile?.full_name, pages_declared: 2, pages_uploaded: 2, doc_number: kind === 'passport' ? profile?.passport_no : `D${Math.floor(rng() * 900000 + 100000)}`, issue_date: '2021-05-12', issuing_country: 'AE', ...meta } });
}

function shiftCase(id, days) {
  if (!days) return;
  const d = `-${days} days`;
  const t = (table, cols, where) => cols.forEach((col) => run(`UPDATE ${table} SET ${col} = CASE WHEN ${col} IS NULL THEN NULL ELSE datetime(${col}, '${d}') END WHERE ${where}`, id));
  t('cases', ['created_at', 'updated_at', 'first_response_at', 'quoted_at', 'closed_at', 'next_update_due'], 'id = ?');
  t('case_events', ['ts'], 'case_id = ?'); t('case_tasks', ['created_at', 'completed_at', 'due_at', 'scheduled_at'], 'case_id = ?');
  t('quotes', ['created_at', 'accepted_at'], 'case_id = ?'); run(`UPDATE quotes SET valid_until = date(valid_until, '${d}') WHERE case_id = ?`, id);
  t('payments', ['created_at', 'verified_at'], 'case_id = ?'); t('ledger_entries', ['ts'], 'case_id = ?'); t('custody_events', ['captured_at', 'synced_at'], 'case_id = ?');
  t('documents', ['created_at'], 'case_id = ?'); t('provider_settlements', ['created_at', 'paid_at'], 'case_id = ?'); t('provider_feedback', ['created_at'], 'case_id = ?');
  t('messages', ['created_at'], 'case_id = ?'); t('refunds', ['created_at', 'paid_at'], 'case_id = ?');
  run(`UPDATE cases SET target_date = CASE WHEN target_date IS NULL THEN NULL ELSE date(target_date, '${d}') END WHERE id = ?`, id);
}

const ORDER = ['customer_action_required', 'ready_for_review', 'quotation_awaiting_approval', 'awaiting_payment', 'assigned', 'collected', 'submitted', 'authority_pending', 'completed', 'delivered'];
const at = (s) => ORDER.indexOf(s);

/** Drive a case through the REAL workflow up to a target state. */
function runCase({ customer, service, profile, org, docCount = 1, pickup, expedited, provider, to = 'customer_action_required', ago = 3, target, extraDocs = ['passport'], purpose, dest, clientRef, clientAlias, route, apostille, poNumber, ccId, channel, fail, paymentMethod = 'card', agentKey, rejectTo, acceptor }) {
  const staff = U.ops; const agent = U[agentKey || 'agent_dxb'];
  const c0 = createCase(customer, { serviceSlug: service, profileId: profile?.id, orgId: org?.id, docCount, pickupEmirate: pickup, deliveryEmirate: pickup, expedited, destinationCountry: dest || 'India', purpose: purpose || 'Study abroad', targetDate: target, clientRef, clientAlias, routeSlug: route, apostille, poNumber, costCenterId: ccId, channel: channel || 'web' });
  let c = get('SELECT * FROM cases WHERE id = ?', c0.id);
  const svc = getService(service);
  const finish = () => {
    const closed = ['completed', 'dispatched', 'delivered'].includes(get('SELECT status FROM cases WHERE id = ?', c.id).status);
    const dur = closed ? 3 + Math.floor(rng() * 10) : 0; // realistic turnaround: case opened `dur` days before it closed
    shiftCase(c.id, ago + dur);
    if (closed) {
      const f = `+${dur} days`;
      run(`UPDATE cases SET closed_at = datetime(closed_at, '${f}'), updated_at = datetime(updated_at, '${f}') WHERE id = ?`, c.id);
      run(`UPDATE case_events SET ts = datetime(ts, '${f}') WHERE case_id = ? AND (to_status IN ('completed','dispatched','delivered') OR type IN ('custody_return','task_done','stage_done'))`, c.id);
      run(`UPDATE ledger_entries SET ts = datetime(ts, '${f}') WHERE case_id = ? AND account IN ('service_fee_revenue')`, c.id);
      run(`UPDATE custody_events SET captured_at = datetime(captured_at, '${f}'), synced_at = datetime(synced_at, '${f}') WHERE case_id = ? AND type = 'return'`, c.id);
      run(`UPDATE provider_settlements SET created_at = datetime(created_at, '${f}') WHERE case_id = ?`, c.id);
      run(`UPDATE provider_feedback SET created_at = datetime(created_at, '${f}') WHERE case_id = ?`, c.id);
      const late = rng() < 0.18;
      run("UPDATE cases SET target_date = date(closed_at, ?) WHERE id = ? AND target_date IS NULL", late ? '-2 days' : `+${1 + Math.floor(rng() * 4)} days`, c.id);
    }
    return get('SELECT * FROM cases WHERE id = ?', c.id);
  };
  if (at(to) < 1 && to !== 'rejected' && to !== 'correction_required') return finish();
  const kindFor = { 'educational-attestation': 'degree', 'personal-attestation': 'birth_certificate', 'commercial-attestation': 'commercial_invoice', 'legal-translation': 'source_document' }[service] || 'document';
  for (let i = 0; i < docCount; i++) upload(customer, c, profile, kindFor);
  for (const k of extraDocs) upload(customer, c, profile, k);
  c = submitForReview(c, customer).case;
  update('cases', c.id, { first_response_at: nowIso() });
  if (to === 'ready_for_review') return finish();
  if (provider) chooseProvider(c, customer, P[provider].id);
  c = get('SELECT * FROM cases WHERE id = ?', c.id);
  const q = draftQuote(c, staff, { emergencyLimit: pickup ? 100 : 0 });
  issueQuote(c, q.id, staff);
  c = get('SELECT * FROM cases WHERE id = ?', c.id);
  if (to === 'quotation_awaiting_approval') return finish();
  const accepted = acceptQuote(c, q.id, acceptor || customer, { method: paymentMethod });
  c = get('SELECT * FROM cases WHERE id = ?', c.id);
  if (paymentMethod === 'credit_account') c = get('SELECT * FROM cases WHERE id = ?', c.id);
  if (to === 'awaiting_payment') return finish();
  if (accepted.payment.status !== 'verified') verifyPayment(accepted.payment.id, `mock_seed_${c.id}`);
  c = assignAfterPayment(get('SELECT * FROM cases WHERE id = ?', c.id), staff);
  const tasks = () => all("SELECT * FROM case_tasks WHERE case_id = ? AND kind = 'pickup' AND status = 'open'", c.id);
  for (const t of tasks()) assignAgent(c, t.id, agent.id, staff, nowIso());
  if (to === 'assigned') return finish();
  const pk = tasks()[0];
  recordCustody(c, agent, { type: 'pickup', task_id: pk?.id, location: pickup || 'Dubai', from_party: customer.name, to_party: agent.name, ack_name: customer.name, ack_method: 'in_person', item_summary: `${docCount} document(s) sealed`, client_event_id: `seed-${c.id}-pk` });
  if (!pk) { try { transition(get('SELECT * FROM cases WHERE id = ?', c.id), 'collected', agent, { silent: true }); } catch { /* no pickup path */ } }
  c = get('SELECT * FROM cases WHERE id = ?', c.id);
  if (to === 'collected') return finish();
  const prov = U[`prov_${provider}`] || U.prov_capital;
  recordCustody(c, prov, { type: 'submission', authority_ref: `AUTH-${c.id}${Math.floor(rng() * 900 + 100)}`, location: 'Authority counter', client_event_id: `seed-${c.id}-sub` });
  c = get('SELECT * FROM cases WHERE id = ?', c.id);
  if (to === 'submitted') return finish();
  const route2 = c.route_id ? getRoute(c.route_id) : null;
  if (to === 'authority_pending' || to === 'rejected' || to === 'correction_required') {
    if (route2) completeStage(c, prov, { seq: 1, evidence: `RCPT-${c.id}-1` });
    c = get('SELECT * FROM cases WHERE id = ?', c.id);
    if (c.status === 'submitted') c = transition(c, 'authority_pending', prov, { silent: true });
    if (to === 'rejected' || to === 'correction_required') {
      c = markRejected(c, staff, { reason: fail || 'Attestation stamp on page 2 is not legible to the receiving authority; re-scan needed', evidence: 'Authority return note scan #A-88', responsible: pick(['customer', 'provider', 'authority']), alternatives: [{ label: 'Re-submit with a certified true copy (no additional authority fee)', cost: 0 }, { label: 'Expedite with embassy appointment', cost: 150 }, { label: 'Cancel and refund unused amounts', type: 'cancel', cost: 0 }] });
      if (to === 'correction_required') c = chooseRecovery(c, customer, 0);
    }
    return finish();
  }
  if (route2) for (const st of route2.stages.filter((s) => s.necessity === 'required' && s.owner !== 'emirattest')) { c = get('SELECT * FROM cases WHERE id = ?', c.id); if (['completed', 'delivered'].includes(c.status)) break; completeStage(c, prov, { seq: st.seq, evidence: `RCPT-${c.id}-${st.seq}` }); }
  c = get('SELECT * FROM cases WHERE id = ?', c.id);
  if (c.status !== 'completed' && !['dispatched', 'delivered'].includes(c.status)) c = markCompleted(c, staff);
  if (to === 'completed') return finish();
  const dt = all("SELECT * FROM case_tasks WHERE case_id = ? AND kind = 'delivery' AND status = 'open'", c.id)[0];
  if (dt) assignAgent(c, dt.id, agent.id, staff, nowIso());
  recordCustody(get('SELECT * FROM cases WHERE id = ?', c.id), agent, { type: 'return', task_id: dt?.id, location: pickup || 'Dubai', from_party: agent.name, to_party: customer.name, ack_name: customer.name, ack_method: 'id_check_and_signature', item_summary: 'Attested originals returned', client_event_id: `seed-${c.id}-ret` });
  c = get('SELECT * FROM cases WHERE id = ?', c.id);
  if (c.provider_id && rng() > 0.25) insert('provider_feedback', { provider_id: c.provider_id, case_id: c.id, rating: pick([5, 5, 4, 4, 4, 3, 5]), comment: pick(['Quick and clear updates', 'Documents returned safely', 'Smooth process', 'Took a day longer than hoped', 'Very professional']), verified: 1 });
  return finish();
}

